# ---------------------------------------------------------------- 6-сабақ
CAP = ("class Replica:\n"
       "    def __init__(self, name):\n"
       "        self.name, self.value, self.version = name, 'бос', 0\n\n"
       "def write(nodes, reachable, value, mode):\n"
       "    \"\"\"mode='CP': көпшілікке жете алмаса бас тартады; 'AP': қолжетімдіге жазады\"\"\"\n"
       "    ok = [n for n in nodes if n.name in reachable]\n"
       "    if mode == 'CP' and len(ok) <= len(nodes) // 2:\n"
       "        return 'қате: көпшілік жоқ (қолжетімсіз)'\n"
       "    for n in ok:\n"
       "        n.value, n.version = value, n.version + 1\n"
       "    return f'жазылды: {[n.name for n in ok]}'\n\n"
       "def read(nodes, reachable, mode):\n"
       "    ok = [n for n in nodes if n.name in reachable]\n"
       "    if mode == 'CP' and len(ok) <= len(nodes) // 2:\n"
       "        return 'қате: көпшілік жоқ (қолжетімсіз)'\n"
       "    return max(ok, key=lambda n: n.version).value\n\n"
       "for mode in ('CP', 'AP'):\n"
       "    nodes = [Replica(x) for x in 'XYZ']\n"
       "    # желі бөлінді: клиент 1 тек X-ті көреді, клиент 2 - Y мен Z-ті\n"
       "    print(mode, '| клиент 1 жазады:', write(nodes, {'X'}, 'Алматы', mode))\n"
       "    print(mode, '| клиент 2 оқиды: ', read(nodes, {'Y', 'Z'}, mode))")

