# ---------------------------------------------------------------- 7-сабақ
ELECT = ("import random\n\n"
         "def election(n, term, timeouts, alive):\n"
         "    \"\"\"Бір мерзімдегі сайлау: таймауты бірінші біткен тірі түйін кандидат болады.\n"
         "    Әр түйін бір мерзімде бір рет қана дауыс береді.\"\"\"\n"
         "    voted = {}\n"
         "    order = sorted((t, i) for i, t in enumerate(timeouts) if alive[i])\n"
         "    for _, cand in order:\n"
         "        votes = 0\n"
         "        for v in range(n):\n"
         "            if alive[v] and voted.get(v) in (None, cand):\n"
         "                voted[v] = cand\n"
         "                votes += 1\n"
         "        if votes * 2 > n:\n"
         "            return cand, votes\n"
         "    return None, 0\n\n"
         "rng = random.Random(3)\n"
         "n = 5\n"
         "alive = [True] * n\n"
         "for term in range(1, 5):\n"
         "    timeouts = [rng.randint(150, 300) for _ in range(n)]\n"
         "    if term == 3:\n"
         "        alive = [True, True, False, False, False]    # үш түйін құлады\n"
         "    leader, votes = election(n, term, timeouts, alive)\n"
         "    print(f'мерзім {term}: таймауттар {timeouts} ->', f'көшбасшы {leader} ({votes} дауыс)' if leader is not None else 'көшбасшы жоқ (көпшілік жоқ)')")

