RLOG = ("def commit_index(match, n):\n"
        "    \"\"\"match: әр түйінде көшбасшымен сәйкес келетін журналдың ұзындығы (көшбасшының өзі де).\n"
        "    Көпшілікте бар ең ұзын префикс - бекітілген.\"\"\"\n"
        "    s = sorted(match, reverse=True)\n"
        "    return s[n // 2]\n\n"
        "leader_log = [(1, 'x=1'), (1, 'y=2'), (2, 'x=3'), (2, 'z=0'), (2, 'y=5')]   # (мерзім, команда)\n"
        "match = [5, 3, 4, 1, 2]       # 0-түйін - көшбасшы\n"
        "c = commit_index(match, len(match))\n"
        "print('бекітілген:', c, leader_log[:c])\n\n"
        "def apply(log, upto):\n"
        "    state = {}\n"
        "    for _, cmd in log[:upto]:\n"
        "        k, v = cmd.split('=')\n"
        "        state[k] = int(v)\n"
        "    return state\n"
        "print('күй машинасы:', apply(leader_log, c))\n\n"
        "# Журналдардың сәйкестігін тексеру (AppendEntries): алдыңғы жазбаның мерзімі сәйкес пе?\n"
        "follower = [(1, 'x=1'), (1, 'y=2'), (1, 'ескі')]\n"
        "prev_index, prev_term = 2, 1\n"
        "ok = len(follower) >= prev_index and follower[prev_index - 1][0] == prev_term\n"
        "if ok:\n"
        "    follower = follower[:prev_index] + leader_log[prev_index:]\n"
        "print('ізбасар:', follower)")

