# ---------------------------------------------------------------- 9-сабақ
RING = ("import bisect, hashlib\n\n"
        "def h(s):\n"
        "    return int(hashlib.md5(s.encode()).hexdigest()[:8], 16)    # детерминирленген хэш\n\n"
        "class Ring:\n"
        "    def __init__(self, nodes, vnodes=50):\n"
        "        self.points = sorted((h(f'{n}#{i}'), n) for n in nodes for i in range(vnodes))\n"
        "        self.keys = [p for p, _ in self.points]\n"
        "    def owner(self, key):\n"
        "        i = bisect.bisect(self.keys, h(key)) % len(self.points)\n"
        "        return self.points[i][1]\n\n"
        "keys = [f'user{i}' for i in range(2000)]\n"
        "before = Ring(['A', 'B', 'C', 'D'])\n"
        "after = Ring(['A', 'B', 'C', 'D', 'E'])\n"
        "moved = sum(before.owner(k) != after.owner(k) for k in keys)\n"
        "print('консистентті хэштеу: көшкен кілттер', round(100 * moved / len(keys), 1), '%')\n\n"
        "mod_moved = sum(h(k) % 4 != h(k) % 5 for k in keys)\n"
        "print('h(k) mod N:           көшкен кілттер', round(100 * mod_moved / len(keys), 1), '%')\n"
        "load = {}\n"
        "for k in keys:\n"
        "    load[after.owner(k)] = load.get(after.owner(k), 0) + 1\n"
        "print('жүктеме:', dict(sorted(load.items())))")

