# ---------------------------------------------------------------- 10-сабақ
SAGA = ("log = []\n\n"
        "def step(name, fail=False):\n"
        "    def run(ctx):\n"
        "        if fail:\n"
        "            raise RuntimeError(f'{name} сәтсіз')\n"
        "        ctx[name] = True\n"
        "        log.append(f'+ {name}')\n"
        "    def undo(ctx):\n"
        "        ctx.pop(name, None)\n"
        "        log.append(f'- {name} (компенсация)')\n"
        "    return name, run, undo\n\n"
        "def saga(steps, ctx):\n"
        "    done = []\n"
        "    for name, run, undo in steps:\n"
        "        try:\n"
        "            run(ctx)\n"
        "            done.append(undo)\n"
        "        except RuntimeError as e:\n"
        "            log.append(f'! {e}')\n"
        "            for u in reversed(done):\n"
        "                u(ctx)\n"
        "            return 'кері қайтарылды'\n"
        "    return 'аяқталды'\n\n"
        "ctx = {}\n"
        "result = saga([step('орын брондау'), step('төлем алу'), step('билет шығару', fail=True)], ctx)\n"
        "print(result, ctx)\n"
        "print('\\n'.join(log))")

